def replace(old, new):
    global s
    assert s.count(old) == 1, (s.count(old), old[:80])
    s = s.replace(old, new)

def section(start, end, content):
    global s
    a, b = s.index(start), s.index(end)
    s = s[:a] + content.strip() + '\n\n' + s[b:]

